create table if not exists public.billing_subscription_guards (provider text not null check (provider in ('stripe','asaas')), user_id text not null, external_id text not null, status text not null default 'active', created_at timestamptz not null default now(), updated_at timestamptz not null default now(), primary key(provider,user_id)); alter table public.billing_subscription_guards enable row level security; revoke all on public.billing_subscription_guards from anon, authenticated;
